mapper.select:
SELECT * FROM settlement_monitoring


        AND monitor_type = #{monitorType}


        AND alert_level = #{alertLevel}


        AND DATE(monitor_time) >= #{startDate}


        AND DATE(monitor_time) <= #{endDate}


        AND org_id = #{orgId}


ORDER BY monitor_time DESC

SELECT * FROM settlement_monitoring
WHERE monitor_type = #{monitorType}
AND DATE(monitor_time) BETWEEN #{startDate} AND #{endDate}
AND org_id = #{orgId}
ORDER BY monitor_time ASC

SELECT alert_level, COUNT(*) as count, COUNT(CASE WHEN is_alert_sent = 1 THEN 1 END) as sentCount, MAX(monitor_time) as lastAlertTime FROM settlement_monitoring WHERE alert_level IS NOT NULL AND alert_level != 'INFO' AND org_id = #{orgId}
AND DATE(monitor_time) >= #{startDate}
AND DATE(monitor_time) <= #{endDate}
GROUP BY alert_level ORDER BY CASE alert_level WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 ELSE 4 END

SELECT monitor_type, COUNT(*) as recordCount, AVG(success_rate) as avgSuccessRate, AVG(avg_processing_time) as avgProcessingTime, AVG(health_score) as avgHealthScore, COUNT(CASE WHEN alert_level IN ('CRITICAL', 'HIGH') THEN 1 END) as alertCount, MAX(monitor_time) as lastMonitorTime FROM settlement_monitoring WHERE org_id = #{orgId}
AND DATE(monitor_time) >= #{startDate}
AND DATE(monitor_time) <= #{endDate}
GROUP BY monitor_type ORDER BY monitor_type

mapper.delete:
DELETE FROM settlement_monitoring
WHERE org_id = #{orgId}
AND monitor_time < DATE_SUB(NOW(), INTERVAL #{retentionDays} DAY)

mapper.select:
SELECT * FROM settlement_monitoring
WHERE monitor_type = #{monitorType}
AND org_id = #{orgId}
ORDER BY monitor_time DESC
LIMIT 1

SELECT * FROM settlement_monitoring
WHERE org_id = #{orgId}
AND (
    success_rate < #{minSuccessRate}
    OR avg_processing_time > #{maxProcessingTime}
    OR health_score < #{minHealthScore}
    OR system_load > #{maxSystemLoad}
    OR memory_usage > #{maxMemoryUsage}
    OR cpu_usage > #{maxCpuUsage}
)
AND monitor_time >= DATE_SUB(NOW(), INTERVAL 1 HOUR)
ORDER BY monitor_time DESC
